{"cards": [{"node_code": "N_08f6b0ed6b35b758", "definition": "研究作用于桥梁结构上的各类外力及其效应，涵盖恒载、活载、风载、地震作用、温度作用及冲击荷载的力学模型、标准取值与组合分析。", "boundary": "本节点聚焦于“荷载”本身及其力学定义。边界在于区分“荷载分析”与“结构响应”（响应归振动、强度等节点）；区分“荷载标准”与“设计应用”（具体规范条文应用归勘测设计）。若涉及荷载试验实测数据，侧重力学原理归本节点，侧重试验方法归试验观测。", "includes": ["桥梁恒载、活载、风荷载、地震作用等力学模型与计算", "荷载组合原则、动力系数及冲击系数分析", "特殊荷载（如制动力、离心力）的力学机理"], "excludes": ["基于荷载结果的结构强度校核与疲劳寿命计算", "桥梁具体构件的几何尺寸与构造细节", "荷载试验的现场实施方法与设备操作"], "sibling_distinctions": [{"other_code": "N_48657fde4034fbff", "rule": "本节点侧重荷载的输入与定义；振动节点侧重结构在荷载作用下的动态响应与减振措施。"}, {"other_code": "N_4ae20505c98a6cf6", "rule": "本节点侧重外力来源与大小；强度节点侧重结构抵抗外力的能力与损伤演化。"}, {"other_code": "N_7202102f612e8c38", "rule": "本节点侧重荷载作用；应力节点侧重荷载在结构内部产生的应力分布与温度效应。"}], "cross_boundary_rule": "若内容涉及荷载与结构响应的耦合分析，侧重荷载模型归本节点，侧重响应机理归相应力学节点。"}, {"node_code": "N_48657fde4034fbff", "definition": "研究桥梁结构在动力荷载作用下的振动特性、动力响应机理，以及用于控制或减轻振动的减振、隔振设备与技术的力学原理。", "boundary": "本节点聚焦于“动态力学”与“振动控制”。边界在于区分“振动分析”与“静力分析”（静力归应力或强度）；区分“减振设备”与“结构构造”（设备侧重功能部件，构造侧重整体形态）。若涉及具体减振器制造工艺归建筑材料或制造，侧重力学性能归本节点。", "includes": ["桥梁自振频率、振型、阻尼比等动力特性分析", "风致振动、车致振动、地震响应等动力效应研究", "减振、隔振、调谐质量阻尼器等设备的力学原理与应用"], "excludes": ["桥梁静力荷载下的应力分布与强度校核", "减振设备的材料配方、生产工艺及制造细节", "桥梁整体线形设计与几何构造"], "sibling_distinctions": [{"other_code": "N_08f6b0ed6b35b758", "rule": "本节点侧重结构对荷载的动态响应；荷载节点侧重荷载本身的定义与计算。"}, {"other_code": "N_4ae20505c98a6cf6", "rule": "本节点侧重动态载荷下的振动行为；强度节点侧重静态或动态载荷下的材料失效与疲劳损伤。"}, {"other_code": "N_7202102f612e8c38", "rule": "本节点侧重时域或频域的动态响应；应力节点侧重稳态或准静态的应力分布。"}], "cross_boundary_rule": "若内容涉及振动导致的疲劳损伤，侧重振动机理归本节点，侧重损伤累积归强度与疲劳节点。"}, {"node_code": "N_4ae20505c98a6cf6", "definition": "研究桥梁结构及构件在荷载作用下的强度极限、稳定性、疲劳裂纹扩展及损伤演化规律，涵盖材料失效机理与寿命评估理论。", "boundary": "本节点聚焦于“材料/结构失效”与“耐久性力学”。边界在于区分“强度/疲劳”与“应力分析”（应力侧重分布，本节点侧重失效判据）；区分“疲劳损伤”与“振动”（振动侧重运动，本节点侧重损伤累积）。若涉及具体材料微观组织归建筑材料，侧重宏观力学行为归本节点。", "includes": ["桥梁构件的强度理论、极限承载力及稳定性分析", "疲劳裂纹萌生、扩展规律及疲劳寿命预测", "结构损伤识别、评估及剩余寿命分析理论"], "excludes": ["桥梁荷载标准与组合计算", "桥梁振动特性分析与减振设备原理", "桥梁具体构件的几何构造与材料生产工艺"], "sibling_distinctions": [{"other_code": "N_08f6b0ed6b35b758", "rule": "本节点侧重结构抵抗破坏的能力；荷载节点侧重施加在结构上的外力。"}, {"other_code": "N_48657fde4034fbff", "rule": "本节点侧重长期或循环载荷下的损伤累积；振动节点侧重瞬时或周期性动态响应。"}, {"other_code": "N_7202102f612e8c38", "rule": "本节点侧重应力导致的失效后果；应力节点侧重应力场本身的分布与计算。"}], "cross_boundary_rule": "若内容涉及振动疲劳，侧重振动激励归振动节点，侧重疲劳损伤机理归本节点。"}]}
